import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./AdminPage.css";

const BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:8081";

function AdminPage() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("dashboard");

  const [totalSlots, setTotalSlots] = useState(10); 
  const [bookings, setBookings] = useState([]);
  const [facilities, setFacilities] = useState([]);
  const [analytics, setAnalytics] = useState([]);
  const [faqs, setFaqs] = useState([]);
  const [replyText, setReplyText] = useState({});
  const [editFacilityId, setEditFacilityId] = useState(null);

  const [loadingBookings, setLoadingBookings] = useState(true);
  const [loadingFacilities, setLoadingFacilities] = useState(true);
  const [loadingAnalytics, setLoadingAnalytics] = useState(true);
  const [loadingFaqs, setLoadingFaqs] = useState(true);

  useEffect(() => {
    fetchBookings();
    fetchFacilities();
    fetchAnalytics();
    fetchFaqs();
  }, []);

  const fetchBookings = () => {
    axios.get(`${BASE_URL}/api/bookings`)
      .then(res => {
        setBookings(res.data);
        setLoadingBookings(false);
      })
      .catch(() => setLoadingBookings(false));
  };

  const fetchFacilities = () => {
    axios.get(`${BASE_URL}/facilities`)
      .then(res => {
        setFacilities(res.data);
        setLoadingFacilities(false);
      })
      .catch(() => setLoadingFacilities(false));
  };

  const fetchAnalytics = () => {
    axios.get(`${BASE_URL}/facility-analytics`)
      .then(res => {
        setAnalytics(res.data);
        setLoadingAnalytics(false);
      })
      .catch(() => setLoadingAnalytics(false));
  };

  const fetchFaqs = () => {
    axios.get(`${BASE_URL}/faqs`)
      .then(res => setFaqs(res.data))
      .catch(() => setLoadingFaqs(false));
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate("/admin-login");
  };

  const handleReplyChange = (faqId, value) => {
    setReplyText({ ...replyText, [faqId]: value });
  };

  const handleReplySubmit = (faqId) => {
    if (!replyText[faqId] || replyText[faqId].trim() === "") return;
    axios.put(`${BASE_URL}/faqs/${faqId}`, { reply: replyText[faqId] })
      .then(() => {
        setReplyText({ ...replyText, [faqId]: "" });
        fetchFaqs();
      })
      .catch(err => console.error(err));
  };

  const renderContent = () => {
    if (activeTab === "faq") {
      if (loadingFaqs) return <p>Loading FAQs...</p>;
      if (!faqs.length) return <p>No FAQs submitted.</p>;

      return (
        <div>
          <h2>User Questions</h2>
          <table>
            <thead>
              <tr>
                <th>User ID</th>
                <th>Question</th>
                <th>Reply</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {faqs.map(f => (
                <tr key={f.id}>
                  <td>{f.userId}</td>
                  <td>{f.question}</td>
                  <td>{f.reply || "-"}</td>
                  <td>
                    <input
                      type="text"
                      placeholder="Type your reply..."
                      value={replyText[f.id] || ""}
                      onChange={(e) => handleReplyChange(f.id, e.target.value)}
                    />
                    <button onClick={() => handleReplySubmit(f.id)}>Reply</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }

    // other tabs (dashboard/bookings/facilities/analytics) remain same
  };

  return (
    <div className="admin-dashboard">
      <div className="sidebar">
        <h2>Admin Panel</h2>
        <ul>
          <li onClick={() => setActiveTab("dashboard")}>Dashboard</li>
          <li onClick={() => setActiveTab("bookings")}>View Bookings</li>
          <li onClick={() => setActiveTab("facilities")}>Facilities</li>
          <li onClick={() => setActiveTab("analytics")}>Facility Analytics</li>
          <li onClick={() => setActiveTab("faq")}>User Questions (FAQ)</li>
        </ul>
      </div>

      <div className="main-content">
        <div className="topbar">
          <h1>{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}</h1>
          <button onClick={handleLogout}>Logout</button>
        </div>
        <div className="content-area">{renderContent()}</div>
      </div>
    </div>
  );
}

export default AdminPage;
